#pragma once
#include <string>
using std::string;

// ---- done in earlier lessons ----

struct Drink {
    string customer_name;
    string tea_type;
    string boba_type;
    string topping_list;
};

class BobaCooker {
public:
    BobaCooker(int capacity) : capacity(capacity), servings_left(capacity), refill_count(0) {}
    int getCapacity() const { return capacity; }
    int getServingsLeft() const { return servings_left; }
    int getRefillCount() const { return refill_count; }
    bool setServingsLeft(int n);
    void addBoba(Drink& drink);
private:
    const int capacity;
    int servings_left;
    int refill_count;
};

bool BobaCooker::setServingsLeft(int n) {
    if (n < 0 || n > capacity) return false;
    servings_left = n;
    return true;
}

void BobaCooker::addBoba(Drink& drink) {
    if (servings_left == 0) {
        servings_left = capacity;
        refill_count++;
    }
    servings_left--;
    drink.boba_type = "Boba Pearls";
}

class OrderKiosk {
public:
    void takeOrder(const string& name, Drink& drink) { drink.customer_name = name; }
};

class TeaBrewer {
public:
    void addTea(Drink& drink) { drink.tea_type = "Black Tea"; }
};

class ToppingStation {
public:
    void addToppings(Drink& drink) { drink.topping_list = "Lychee Jelly"; }
};

// ---- this lesson ----

class BobaCafe {
public:
    BobaCafe() : id(++num_created), bobaCooker(3), num_drinks_served(0) {
        // TODO: one more cafe is open
    }
    ~BobaCafe() {
        // TODO: this cafe is closing
    }
    Drink doOrder(const string& customer_name);
    int getId() const { return id; }
    int getDrinksServed() const { return num_drinks_served; }
    static int getNumOpen() { /* TODO */ return 0; }
    static int getTotalServed() { /* TODO */ return 0; }
private:
    static int num_created;
    static int num_open;
    static int total_served;
    const int id;
    OrderKiosk orderKiosk;
    TeaBrewer teaBrewer;
    BobaCooker bobaCooker;
    ToppingStation toppingStation;
    int num_drinks_served;
};

// each static data member is defined once, outside the class (normally in bobacafe.cpp)
int BobaCafe::num_created = 0;
int BobaCafe::num_open = 0;
int BobaCafe::total_served = 0;

Drink BobaCafe::doOrder(const string& customer_name) {
    Drink newDrink;
    orderKiosk.takeOrder(customer_name, newDrink);
    teaBrewer.addTea(newDrink);
    bobaCooker.addBoba(newDrink);
    toppingStation.addToppings(newDrink);
    num_drinks_served++;
    return newDrink;
}

#include "check.h"
#include "cafe.h"

int main() {
    {
        BobaCafe a;
        CHECK_EQ(BobaCafe::getNumOpen(), 1);
        a.doOrder("Customer 0");
        a.doOrder("Customer 1");
    }                                   // a closes here
    CHECK_EQ(BobaCafe::getNumOpen(), 0);
    CHECK_EQ(BobaCafe::getTotalServed(), 2);
    if (submitting()) {
        BobaCafe b;
        {
            BobaCafe c;
            CHECK_EQ(BobaCafe::getNumOpen(), 2);
            c.doOrder("Customer 2");
            CHECK_EQ(BobaCafe::getTotalServed(), 2);   // c hasn't closed yet
        }
        CHECK_EQ(BobaCafe::getNumOpen(), 1);
        CHECK_EQ(BobaCafe::getTotalServed(), 3);
        BobaCafe* p = new BobaCafe();
        CHECK_EQ(BobaCafe::getNumOpen(), 2);
        p->doOrder("Customer 3");
        delete p;
        CHECK_EQ(BobaCafe::getNumOpen(), 1);
        CHECK_EQ(BobaCafe::getTotalServed(), 4);
    }
    return check_done();
}

#pragma once
#include <iostream>

class Speaker {
    double volume;
public:
    // Write the constructor here

    // Write the destructor here

    double getVolume() const { return volume; }
};

#include <sstream>
#include "check.h"
#include "speaker.h"

// Runs one Speaker's whole life and returns everything it printed.
std::string lifeOf(double v, double* seen) {
    std::ostringstream out;
    std::streambuf* old = std::cout.rdbuf(out.rdbuf());
    {
        Speaker s(v);
        *seen = s.getVolume();
    }
    std::cout.rdbuf(old);
    return out.str();
}

int main() {
    double seen = 0;
    CHECK_EQ(lifeOf(7, &seen), "Speaker off.\n");
    CHECK_EQ(seen, 7.0);
    if (submitting()) {
        lifeOf(0.25, &seen);
        CHECK_EQ(seen, 0.25);          // the parameter has to be a double
        lifeOf(-3.5, &seen);
        CHECK_EQ(seen, -3.5);
        std::ostringstream out;
        std::streambuf* old = std::cout.rdbuf(out.rdbuf());
        Speaker* p = new Speaker(2.5);
        std::string afterNew = out.str();
        delete p;
        std::string afterDelete = out.str();
        std::cout.rdbuf(old);
        CHECK_EQ(afterNew, "");                    // the constructor prints nothing
        CHECK_EQ(afterDelete, "Speaker off.\n");   // delete runs the destructor once
    }
    return check_done();
}

