#pragma once

// A growable array that starts with room for 1 int.
class GrowArray {
public:
    GrowArray() : data(new int[1]), cap(1), n(0), copies(0) {}
    ~GrowArray() { delete[] data; }
    GrowArray(const GrowArray&) = delete;            // no copies in this lesson
    GrowArray& operator=(const GrowArray&) = delete;

    int size() const { return n; }
    int capacity() const { return cap; }
    long copyCount() const { return copies; }        // element copies made while growing
    int get(int i) const { return data[i]; }

    void push(int x) {
        // TODO
    }

private:
    int* data;
    int cap;
    int n;
    long copies;
};

#include "check.h"
#include "growarray.h"

int main() {
    GrowArray a;
    for (int i = 1; i <= 8; i++) a.push(i * 10);
    CHECK_EQ(a.size(), 8);
    CHECK_EQ(a.capacity(), 8);
    CHECK_EQ(a.copyCount(), 7L);
    if (a.size() == 8) CHECK_EQ(a.get(7), 80);
    a.push(90);
    CHECK_EQ(a.capacity(), 16);
    CHECK_EQ(a.copyCount(), 15L);
    if (submitting()) {
        bool ok = a.size() == 9;
        for (int i = 0; ok && i < 9; i++) ok = a.get(i) == (i + 1) * 10;
        CHECK(ok);
        GrowArray one;
        one.push(5);
        CHECK_EQ(one.capacity(), 1);
        CHECK_EQ(one.copyCount(), 0L);
        GrowArray b;
        for (int i = 0; i < 1000; i++) b.push(i);
        CHECK_EQ(b.capacity(), 1024);
        CHECK_EQ(b.copyCount(), 1023L);
        must_finish(5, "push should double the array, not grow it by a constant");
        GrowArray c;
        for (int i = 0; i < 100000; i++) c.push(i);
        must_finish(0);
        CHECK_EQ(c.size(), 100000);
        CHECK_EQ(c.copyCount(), 131071L);
        CHECK(c.copyCount() < 2L * c.size());
        if (c.size() == 100000) CHECK_EQ(c.get(99999), 99999);
    }
    return check_done();
}

