// Test helpers. The caps make a cycle fail instead of hang.
vector<int> toVector(Node* h) { vector<int> v; for (; h && v.size() < 100; h = h->next) v.push_back(h->elt); return v; }
Node* build(vector<int> v) { Node* h = nullptr; for (int i = (int)v.size() - 1; i >= 0; i--) h = new Node{v[i], h}; return h; }
void freeList(Node* h) { std::set<Node*> s; while (h && s.insert(h).second) h = h->next; for (Node* n : s) delete n; }

int main() {
    must_finish(5, "endless loop? Look for a pointer that never moves forward");
    Node* deck = build({7, 2, 9});
    CHECK_EQ(length(deck), 3);
    CHECK(contains(deck, 9));
    CHECK(!contains(deck, 4));
    if (submitting()) {
        CHECK(contains(deck, 7));
        CHECK_EQ(toVector(deck), vector<int>({7, 2, 9}));   // unchanged
        CHECK_EQ(length(nullptr), 0);
        CHECK(!contains(nullptr, 7));
        Node* one = build({4});
        CHECK_EQ(length(one), 1);
        CHECK(contains(one, 4));
        freeList(one);
        Node* big = build(vector<int>(1000, 5));
        CHECK_EQ(length(big), 1000);
        CHECK(!contains(big, 6));
        freeList(big);
    }
    freeList(deck);
    return check_done();
}

