#pragma once

class FullDequeException {};
class EmptyDequeException {};

class PrintDeque {
public:
    PrintDeque(int N) : Q(new int[N]), N(N), f(0), r(0) {}
    ~PrintDeque() { delete[] Q; }
    PrintDeque(const PrintDeque&) = delete;
    PrintDeque& operator=(const PrintDeque&) = delete;

    // ---- done in earlier lessons (it's the circular queue) ----
    int size() const { return (N - f + r) % N; }
    bool isEmpty() const { return f == r; }
    void insertBack(int v) {
        if (size() == N - 1) throw FullDequeException();
        Q[r] = v;
        r = (r + 1) % N;
    }
    int removeFront() {
        if (isEmpty()) throw EmptyDequeException();
        int v = Q[f];
        f = (f + 1) % N;
        return v;
    }
    int first() const {
        if (isEmpty()) throw EmptyDequeException();
        return Q[f];
    }

    // ---- this lesson ----
    void insertFront(int v) {
        // TODO
    }
    int removeBack() {
        // TODO
        return 0;
    }
    int last() const {
        // TODO
        return 0;
    }

private:
    int* Q;
    int N;
    int f;   // index of the front job
    int r;   // index one past the last job
};

#include "check.h"
#include "deque.h"

bool throws(void (*fn)()) { try { fn(); } catch (...) { return true; } return false; }

int main() {
    PrintDeque d(6);
    d.insertBack(1);
    d.insertBack(2);
    d.insertFront(9);             // f wraps backward
    CHECK_EQ(d.first(), 9);
    CHECK_EQ(d.last(), 2);
    CHECK_EQ(d.removeBack(), 2);
    CHECK_EQ(d.size(), 2);
    if (submitting()) {
        CHECK_EQ(d.removeBack(), 1);
        CHECK_EQ(d.last(), 9);    // last wraps too
        CHECK_EQ(d.removeBack(), 9);
        CHECK(d.isEmpty());
        for (int i = 0; i < 5; i++) d.insertFront(i);
        CHECK_EQ(d.size(), 5);
        for (int i = 0; i < 5; i++) CHECK_EQ(d.removeBack(), i);
        PrintDeque e(3);          // r == 0 when removeBack steps back
        e.insertBack(4);
        e.removeFront();
        e.insertBack(5);
        e.insertBack(6);
        CHECK_EQ(e.last(), 6);
        CHECK_EQ(e.removeBack(), 6);
        CHECK_EQ(e.first(), 5);
        CHECK(throws([] { PrintDeque a(3); a.insertFront(1); a.insertFront(2); a.insertFront(3); }));
        CHECK(throws([] { PrintDeque a(3); a.removeBack(); }));
        CHECK(throws([] { PrintDeque a(3); a.last(); }));
    }
    return check_done();
}

lessons.readme:
# Sequential Search in C++

Here's what the lecture's sequential search looks like on a singly linked list. The array version, which you'll write, has the same shape: a loop, one comparison per element, and -1 when the loop runs out.

```cpp
int sequentialSearchIndex(Node* head, int key) {
    int i = 0;
    for (Node* cur = head; cur != nullptr; cur = cur->next, i++) {
        if (cur->elt == key) {
            return i;
        }
    }
    return -1;
}
```

Sequential search works on anything you can walk through: unsorted arrays, sorted arrays, linked lists. That's its one big advantage. Its weakness is that it can't skip anything.

We're going to build up `search.h` over the next few lessons, starting with this one.

## Assignment

The registrar's directory is a plain C-style array of student IDs.

1. [ ] Complete `sequentialSearch(arr, n, key)`. Check `arr[0]`, `arr[1]`, … in order and return the index of the **first** element equal to `key`.
2. [ ] Return `-1` if no element matches, including when `n` is 0.

