#pragma once
#include <vector>
using std::vector;

enum State { EMPTY, OCCUPIED, DELETED };

struct HashTable {
    vector<int> keys, values;
    vector<State> state;
    HashTable(int m) : keys(m), values(m), state(m, EMPTY) {}
    int capacity() const { return keys.size(); }
};

// ---- done in earlier lessons ----

int* find(HashTable& t, int k) {
    int m = t.capacity();
    for (int i = 0, b = k % m; i < m; i++, b = (b + 1) % m) {
        if (t.state[b] == EMPTY) return nullptr;
        if (t.state[b] == OCCUPIED && t.keys[b] == k) return &t.values[b];
    }
    return nullptr;
}

bool insert(HashTable& t, int k, int v) {
    if (int* old = find(t, k)) { *old = v; return true; }
    int m = t.capacity();
    for (int i = 0, b = k % m; i < m; i++, b = (b + 1) % m)
        if (t.state[b] == EMPTY) {
            t.keys[b] = k; t.values[b] = v; t.state[b] = OCCUPIED;
            return true;
        }
    return false;
}

bool erase(HashTable& t, int k) {
    int m = t.capacity();
    for (int i = 0, b = k % m; i < m; i++, b = (b + 1) % m) {
        if (t.state[b] == EMPTY) return false;
        if (t.state[b] == OCCUPIED && t.keys[b] == k) { t.state[b] = DELETED; return true; }
    }
    return false;
}

double effectiveLoadFactor(const HashTable& t) {
    int used = 0;
    for (State s : t.state)
        if (s != EMPTY) used++;
    return (double)used / t.capacity();
