    for (int b = 0; b < t.capacity(); b++)
        if (t.state[b] == OCCUPIED && t.keys[b] == k) return b;
    return -1;
}
int copies(const HashTable& t, int k) {
    int c = 0;
    for (int b = 0; b < t.capacity(); b++) c += t.state[b] == OCCUPIED && t.keys[b] == k;
    return c;
}
int valueOf(HashTable& t, int k) {
