vector<int> merge(const vector<int>& a, const vector<int>& b) {
    vector<int> s;
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) s.push_back(a[i++]);
        else s.push_back(b[j++]);
    }
    while (i < a.size()) s.push_back(a[i++]);
    while (j < b.size()) s.push_back(b[j++]);
    return s;
}

