using std::vector;

// ---- done in earlier lessons ----

void bubblePass(vector<int>& A, int i) {
    for (int j = 0; j < (int)A.size() - 1 - i; j++)
        if (A[j] > A[j + 1]) std::swap(A[j], A[j + 1]);
}

void bubbleSort(vector<int>& A) {
    for (int i = 0; i < (int)A.size() - 1; i++) bubblePass(A, i);
}

void selectionPass(vector<int>& A, int i) {
    int min = i;
    for (int j = i + 1; j < (int)A.size(); j++)
        if (A[j] < A[min]) min = j;
    std::swap(A[i], A[min]);
}

void selectionSort(vector<int>& A) {
    for (int i = 0; i < (int)A.size() - 1; i++) selectionPass(A, i);
}

void insertionPass(vector<int>& A, int i) {
    int temp = A[i], j = i - 1;
    if (temp < A[j]) {
        while (j >= 0 && temp < A[j]) {
            A[j + 1] = A[j];
            j--;
        }
        A[j + 1] = temp;
    }
}

void insertionSort(vector<int>& A) {
    for (int i = 1; i < (int)A.size(); i++) insertionPass(A, i);
}

vector<int> merge(const vector<int>& a, const vector<int>& b) {
    vector<int> s;
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) s.push_back(a[i++]);
        else s.push_back(b[j++]);
    }
    while (i < a.size()) s.push_back(a[i++]);
    while (j < b.size()) s.push_back(b[j++]);
    return s;
}

vector<int> mergeSort(const vector<int>& S) {
    if (S.size() <= 1) return S;
    size_t half = S.size() / 2;
    vector<int> S1(S.begin(), S.begin() + half), S2(S.begin() + half, S.end());
    return merge(mergeSort(S1), mergeSort(S2));
}

