    for (TreeNode* p : all) delete p;
}

TreeNode* balanced(int lo, int hi) {     // a perfectly balanced BST of the even keys 2*lo .. 2*hi
    if (lo > hi) return nullptr;
    int mid = lo + (hi - lo) / 2;
    return new TreeNode{2 * mid, balanced(lo, mid - 1), balanced(mid + 1, hi)};
}

TreeNode* build(std::initializer_list<int> keys) {   // inserts in order, the same way the lesson does
    TreeNode* t = nullptr;
    for (int k : keys) {
        TreeNode** p = &t;
        while (*p) p = k < (*p)->info ? &(*p)->left : &(*p)->right;
        *p = N(k);
    }
    return t;
}

int main() {
    TreeNode* good = N(50, N(30, N(20), N(40)), N(70, N(60), N(80)));
    TreeNode* sneaky = N(50, N(30, N(20), N(55)), N(70));
    CHECK(isBST(good));
