        TreeNode* dup = N(10, N(5), N(10));
        TreeNode* dupLeft = N(10, N(10), N(15));
        TreeNode* chain = N(1, nullptr, N(2, nullptr, N(3, nullptr, N(4))));
        CHECK(isBST(one));
        CHECK(!isBST(swapped));
        CHECK(!isBST(deepRight));
        CHECK(!isBST(dup));
        CHECK(!isBST(dupLeft));
