struct TreeNode {
    int info;
    TreeNode* left;
    TreeNode* right;
};

// ---- done in earlier lessons ----

bool between(TreeNode* t, long lo, long hi) {
    if (t == nullptr) return true;
    if (t->info <= lo || t->info >= hi) return false;
    return between(t->left, lo, t->info) && between(t->right, t->info, hi);
}

bool isBST(TreeNode* t) { return between(t, LONG_MIN, LONG_MAX); }

bool search(TreeNode* root, int key) {
    TreeNode* cur = root;
    while (cur != nullptr) {
        if (key == cur->info) return true;
        else if (key < cur->info) cur = cur->left;
        else cur = cur->right;
    }
    return false;
}

void insert(TreeNode*& root, int key) {
    if (root == nullptr) {
        root = new TreeNode{key, nullptr, nullptr};
        return;
    }
    TreeNode* cur = root;
    while (true) {
        if (key < cur->info) {
            if (cur->left == nullptr) {
                cur->left = new TreeNode{key, nullptr, nullptr};
                return;
            }
            cur = cur->left;
        } else if (cur->info < key) {
            if (cur->right == nullptr) {
                cur->right = new TreeNode{key, nullptr, nullptr};
                return;
            }
            cur = cur->right;
        } else {
            return;   // duplicate key: do nothing
        }
    }
}

void removeTwoChildren(TreeNode* t);   // the next lesson

void remove(TreeNode*& t, int key) {
    if (t == nullptr) return;                          // key isn't in the tree
    if (key < t->info) remove(t->left, key);
    else if (t->info < key) remove(t->right, key);
    else if (t->left != nullptr && t->right != nullptr) removeTwoChildren(t);
    else {                                             // case 1 or case 2
        TreeNode* old = t;
        t = (t->left != nullptr) ? t->left : t->right;
        delete old;
    }
}

void removeTwoChildren(TreeNode* t) {
    TreeNode* qp = t;            // q's parent
    TreeNode* q = t->left;       // left once...
    while (q->right != nullptr) {   // ...then right all the way
        qp = q;
        q = q->right;
    }
    t->info = q->info;
    if (qp == t) t->left = q->left;   // q was t's own left child
    else qp->right = q->left;
    delete q;
}

