vector<int> bfsOrder(const vector<vector<int>>& adj, int s) {
    vector<bool> visited(adj.size(), false);
    vector<int> order;
    std::queue<int> q;
    visited[s] = true;
    q.push(s);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        order.push_back(v);
        for (int w : adj[v])
            if (!visited[w]) {
                visited[w] = true;
                q.push(w);
            }
    }
    return order;
}

