#pragma once
#include <algorithm>
#include <climits>
#include <functional>
#include <queue>
#include <utility>
#include <vector>
using std::vector;
using Edge = std::pair<int, int>;   // {neighbor, length}

const long long INF = LLONG_MAX;

struct ShortestPaths {
    vector<long long> dist;   // -1 if unreachable
    vector<int> prev;         // -1 for the start and for unreachable vertices
};

// ---- done in earlier lessons ----

ShortestPaths dijkstra(const vector<vector<Edge>>& adj, int s) {
    using P = std::pair<long long, int>;   // {dist, vertex}
    int n = adj.size();
    vector<long long> dist(n, INF);
    vector<int> prev(n, -1);
    vector<bool> finished(n, false);
    std::priority_queue<P, vector<P>, std::greater<P>> pq;
    dist[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (finished[u]) continue;          // a stale copy: lazy deletion
        finished[u] = true;
        for (auto [v, len] : adj[u])
            if (dist[u] + len < dist[v]) {
                dist[v] = dist[u] + len;
                prev[v] = u;
                pq.push({dist[v], v});
            }
    }
    for (long long& x : dist)
        if (x == INF) x = -1;
    return {dist, prev};
}

