// what the pieces sell for, or -1 if they aren't a valid way to cut n feet
int sell(const vector<int>& price, const vector<int>& pieces, int n) {
    if ((int)pieces.size() > n) return -1;
    int total = 0, length = 0;
    for (int x : pieces) {
        if (x < 1 || x >= (int)price.size()) return -1;
        total += price[x];
        length += x;
    }
    return length == n ? total : -1;
}

