vector<int> bestCuts(const vector<int>& price, int n) {
    vector<int> best(n + 1, 0), first(n + 1, 0);
    for (int j = 1; j <= n; j++)
        for (int i = 1; i <= j; i++)
            if (price[i] + best[j - i] > best[j]) {
                best[j] = price[i] + best[j - i];
                first[j] = i;
            }
    vector<int> pieces;
    for (int j = n; j > 0; j -= first[j]) pieces.push_back(first[j]);
    return pieces;
}

